# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import round_span, rounded_labels

class RoundSpanTests(unittest.TestCase):
    # ---
    def test_rounds_to_nearest_step(self):
        self.assertEqual(round_span(Span(542, 1027), 15), Span(540, 1020))

    # ---
    def test_halfway_rounds_up(self):
        self.assertEqual(round_span(Span(15, 100), 30), Span(30, 90))

    # ---
    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(601, 604), 15)

class LabelTests(unittest.TestCase):
    # ---
    def test_label_format(self):
        labels = rounded_labels([Span(540, 1035)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    # ---
    def test_one_label_per_span_in_order(self):
        spans = [Span(481, 725), Span(0, 60)]
        labels = rounded_labels(spans, 30)
        self.assertEqual(labels, ["08:00-12:00 (4h 0m)", "00:00-01:00 (1h 0m)"])

    # ---
    def test_empty_input(self):
        self.assertEqual(rounded_labels([], 15), [])

    # ---
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                rounded_labels([Span(540, 600)], step)

    # ---
    def test_every_divisor_of_an_hour_is_accepted(self):
        for step in (1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60):
            self.assertEqual(len(rounded_labels([Span(0, 1440)], step)), 1)

if __name__ == "__main__":
    unittest.main()
